def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count simple paths of exactly K moves, with every starting cell counted."""
    open_cells = [
        r * W + c
        for r in range(H)
        for c in range(W)
        if grid[r][c] == "."
    ]
    if K >= len(open_cells):
        return 0

    neighbors = [[] for _ in range(H * W)]
    for r in range(H):
        for c in range(W):
            cell = r * W + c
            if grid[r][c] != ".":
                continue
            if r > 0 and grid[r - 1][c] == ".":
                neighbors[cell].append(cell - W)
            if r + 1 < H and grid[r + 1][c] == ".":
                neighbors[cell].append(cell + W)
            if c > 0 and grid[r][c - 1] == ".":
                neighbors[cell].append(cell - 1)
            if c + 1 < W and grid[r][c + 1] == ".":
                neighbors[cell].append(cell + 1)

    total = 0

    def search(cell: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        result = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not visited & bit:
                result += search(nxt, remaining - 1, visited | bit)
        return result

    for start in open_cells:
        total += search(start, K, 1 << start)
    return total

