from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the minimum cost of covering each section within the sensor limits."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # For a fixed number of type 1 sensors used, fewer type 2 sensors always
    # dominates. Keep that minimum while processing sections.
    dp = {0: 0}  # total type 1 sensors -> minimum total type 2 sensors
    max1 = min(k1, sum((d + l1 - 1) // l1 for d in sections[:n]))

    for length in sections[:n]:
        max_for_section = (length + l1 - 1) // l1
        options = []
        for count1 in range(max_for_section + 1):
            remaining = max(0, length - count1 * l1)
            count2 = (remaining + l2 - 1) // l2
            options.append((count1, count2))

        next_dp = {}
        for used1, used2 in dp.items():
            for add1, add2 in options:
                total1 = used1 + add1
                total2 = used2 + add2
                if total1 <= max1 and total2 <= k2:
                    if total2 < next_dp.get(total1, float("inf")):
                        next_dp[total1] = total2
        dp = next_dp
        if not dp:
            return -1

    if not dp:
        return -1
    return min(used1 * c1 + used2 * c2
               for used1, used2 in dp.items()
               if used1 <= k1 and used2 <= k2)

