from functools import lru_cache
from math import comb


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words over 1..K whose only missing length-M subsequence is X.

    The result is returned modulo 998244353.
    """
    mod = 998244353

    @lru_cache(None)
    def onto(q: int, n: int) -> int:
        """Words of length n over q letters using every letter."""
        if n < 0:
            return 0
        return sum(
            (-1 if i & 1 else 1) * comb(q, i) * pow(q - i, n, mod)
            for i in range(q + 1)
        ) % mod

    @lru_cache(None)
    def tail_after_first(last_pattern_letter: int, q: int, length: int) -> int:
        """Suffixes where the next needed pattern letter is first, then all q letters occur."""
        answer = 0
        for before in range(length):
            # Before the first matching letter, each position has q-1 choices.
            answer += pow(q - 1, before, mod) * onto(q, length - before - 1)
        return answer % mod

    @lru_cache(None)
    def count(n: int, m: int, k: int, forbidden: tuple[int, ...]) -> int:
        # The constant word a^m is required for every a unless it is X.
        lower_bound = m * k - (1 if len(set(forbidden)) == 1 else 0)
        if n < lower_bound:
            return 0

        if m == 1:
            # Avoid the forbidden letter and use all other letters.
            return onto(k - 1, n)

        prefix_pattern = forbidden[:-1]
        last = forbidden[-1]
        q = k - 1
        answer = 0

        # The last occurrence of last divides the word into a prefix which
        # misses prefix_pattern and a suffix over the other k-1 letters.
        for t in range(n):
            ways_prefix = count(t, m - 1, k, prefix_pattern)
            if not ways_prefix:
                continue
            suffix_length = n - t - 1

            if prefix_pattern[-1] == last:
                # The distinguished prefix is completed at the last letter.
                ways_suffix = onto(q, suffix_length)
            elif last not in prefix_pattern:
                # The prefix already greedily matches prefix_pattern[:-1];
                # the suffix needs its final letter, then all other letters.
                ways_suffix = tail_after_first(
                    prefix_pattern[-1], q, suffix_length
                )
            else:
                # A last inside the prefix pattern cannot be completed before
                # or after its final occurrence.
                continue

            answer = (answer + ways_prefix * ways_suffix) % mod

        return answer

    return count(N, M, K, tuple(X))

