from functools import lru_cache


@lru_cache(maxsize=None)
def _suffix_ways(target: int, slots: int, remaining_sum: int, product_mod: int) -> int:
    """Count digit suffixes with a given sum and final product residue."""
    if remaining_sum < 0 or remaining_sum > 9 * slots:
        return 0
    if slots == 0:
        return int(remaining_sum == 0 and product_mod == 0)

    total = 0
    for digit in range(10):
        total += _suffix_ways(
            target,
            slots - 1,
            remaining_sum - digit,
            (product_mod * digit) % target,
        )
    return total


def _count_up_to(limit: int) -> int:
    if limit <= 0:
        return 0

    digits = [int(ch) for ch in str(limit)]
    width = len(digits)
    total = 0

    # Count every shorter positive number. The leading digit must be nonzero.
    for length in range(1, width):
        for target in range(1, 9 * length + 1):
            for first in range(1, 10):
                total += _suffix_ways(
                    target, length - 1, target - first, first % target
                )

    # Count numbers of the same width that do not exceed limit.
    for target in range(1, 9 * width + 1):
        prefix_sum = 0
        product_mod = 1 % target
        for pos, bound_digit in enumerate(digits):
            first_allowed = 1 if pos == 0 else 0
            for digit in range(first_allowed, bound_digit):
                total += _suffix_ways(
                    target,
                    width - pos - 1,
                    target - prefix_sum - digit,
                    (product_mod * digit) % target,
                )

            prefix_sum += bound_digit
            product_mod = (product_mod * bound_digit) % target
            if prefix_sum > target:
                break
        else:
            if prefix_sum == target and product_mod == 0:
                total += 1

    return total


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

