from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product has divisor sum divisible by 3."""
    if N <= 10000:
        spf = list(range(N + 1))
        for p in range(2, isqrt(N) + 1):
            if spf[p] == p:
                for v in range(p * p, N + 1, p):
                    if spf[v] == v:
                        spf[v] = p
        max_exp = N.bit_length()
        choose = [1] * (max_exp + 1)
        for e in range(1, max_exp + 1):
            choose[e] = choose[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD
        ans = 0
        for n in range(2, N + 1):
            x = n
            residue = 1
            weight = 1
            while x > 1:
                p = spf[x]
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                weight = weight * choose[e] % MOD
                if p == 3:
                    continue
                if p % 3 == 1:
                    residue = residue * (e + 1) % 3
                elif e & 1:
                    residue = 0
            if residue == 0:
                ans = (ans + weight) % MOD
        return ans

    root_n = isqrt(N)
    sieve = bytearray(b"\x01") * (root_n + 1)
    sieve[0] = 0
    if root_n >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(root_n) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:root_n + 1:p] = b"\x00" * (((root_n - start) // p) + 1)
    primes = [p for p in range(2, root_n + 1) if sieve[p]]

    values = list(range(1, root_n + 1))
    values.extend(N // i for i in range(root_n, 0, -1) if N // i > root_n)
    index = {v: i for i, v in enumerate(values)}
    g1 = [0] * len(values)
    g2 = [0] * len(values)
    for i, x in enumerate(values):
        n1 = (x - 1) // 3 + 1 if x >= 1 else 0
        n2 = (x - 2) // 3 + 1 if x >= 2 else 0
        g1[i] = n1 - 1
        g2[i] = n2

    for p in primes:
        if p == 3:
            continue
        p2 = p * p
        pi1_below = g1[index[p - 1]]
        pi2_below = g2[index[p - 1]]
        if p % 3 == 1:
            for ix in range(len(values) - 1, -1, -1):
                x = values[ix]
                if x < p2:
                    break
                j = index[x // p]
                g1[ix] -= g1[j] - pi1_below
                g2[ix] -= g2[j] - pi2_below
        else:
            for ix in range(len(values) - 1, -1, -1):
                x = values[ix]
                if x < p2:
                    break
                j = index[x // p]
                g1[ix] -= g2[j] - pi2_below
                g2[ix] -= g1[j] - pi1_below

    pi_small_1 = [0] * (root_n + 1)
    pi_small_2 = [0] * (root_n + 1)
    c1 = c2 = 0
    for x in range(root_n + 1):
        if x >= 2 and sieve[x]:
            if x % 3 == 1:
                c1 += 1
            elif x % 3 == 2:
                c2 += 1
        pi_small_1[x] = c1
        pi_small_2[x] = c2

    def pi_r(x: int, r: int) -> int:
        if x < 2:
            return 0
        if x <= root_n:
            return pi_small_1[x] if r == 1 else pi_small_2[x]
        return (g1 if r == 1 else g2)[index[x]]

    max_exp = N.bit_length()
    invs = [0, 1]
    for e in range(2, max_exp + 1):
        invs.append(MOD - (MOD // e) * invs[MOD % e] % MOD)

    @lru_cache(None)
    def solve(i: int, x: int, s: int) -> int:
        ans = 1 if s == 0 else 0
        if x <= 1:
            return ans
        previous = primes[i - 1] if i else 1
        root = isqrt(x)
        tail_start = max(previous, root)
        if s == 0:
            ans += M * (pi_r(x, 1) - pi_r(tail_start, 1)
                        + (1 if previous < 3 <= x and root < 3 else 0))
        ans += M * (pi_r(x, 2) - pi_r(tail_start, 2))

        j = i
        while j < len(primes) and primes[j] <= root:
            p = primes[j]
            power = p
            e = 1
            weight = M % MOD
            while power <= x:
                if p == 3:
                    sig = 1
                elif p % 3 == 1:
                    sig = (e + 1) % 3
                else:
                    sig = 0 if e & 1 else 1
                ans += weight * solve(j + 1, x // power, (s * sig) % 3)
                power *= p
                e += 1
                if power <= x:
                    weight = weight * (M + e - 1) % MOD * invs[e] % MOD
            j += 1
        return ans % MOD

    return solve(0, N, 1) % MOD

